<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { Globe, RefreshCw, Plus, Settings2, X, CreditCard, CheckCircle2, Clock3 } from 'lucide-vue-next'
import { api } from '../api'
import { formatTime } from '../utils'
import { operationNames, operationStates, returnStates, terminal, cardState, cancelReason, requestID, refreshDue, markRefreshed, nexovccSettingsPayload, nexovccOperationPayload } from '../nexovcc'
import Pagination from './Pagination.vue'
import MessageBar from './MessageBar.vue'
import PaymentCardStatus from './PaymentCardStatus.vue'

const props=defineProps({defaultPageSize:{type:Number,default:10}})
const data=reactive({cards:[],operations:[],cases:[],products:[],balance:{}})
const cfg=reactive({enabled:false,default_max_accounts:1,single_active_account:true,page_refresh_seconds:30,templates:[],login:'',password:'',fund_password:'',totp_secret:'',clear_totp:false})
const ready=ref(false),busy=ref(false),saving=ref(false),tab=ref('cards'),filter=ref('normal'),search=ref(''),page=ref(1),pageSize=ref(props.defaultPageSize||10),selection=ref([])
const message=reactive({text:'',type:'success'}),job=ref({}),batch=ref(null),dialog=ref(null),privateInfo=ref(null)
let disposed=false,pollTimer,privateTimer
const show=(text,type='success')=>Object.assign(message,{text,type})
const tabs=[{id:'cards',name:'卡片管理'},{id:'returns',name:'账号回款'},{id:'operations',name:'操作记录'},{id:'settings',name:'配置与模板'}]
const running=computed(()=>busy.value||job.value.status==='running'||!!batch.value?.running)
const activeCards=computed(()=>data.cards.filter(r=>r.card.status!=='4'))
const cardTotal=computed(()=>{const rows=activeCards.value;if(!rows.length)return '0.00';if(rows.some(r=>r.card.balance===''))return '待同步';return rows.reduce((s,r)=>s+Math.round(Number(r.card.balance)*100),0)/100})
const selectable=computed(()=>activeCards.value.filter(r=>r.local?.available).length)
const filtered=computed(()=>{
 const rows=tab.value==='cards'?data.cards.filter(r=>filter.value==='closed'?r.card.status==='4':r.card.status!=='4'):tab.value==='returns'?data.cases.filter(c=>c.payment_status==='success'&&c.state!=='unopened'):data.operations
 const q=search.value.trim().toLowerCase();return rows.filter(r=>!q||[r.card?.serial_no,r.card?.last4,r.card?.remark,r.email,r.id,r.last4,r.serial_no].some(v=>String(v||'').toLowerCase().includes(q)))
})
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
watch([tab,filter,search],()=>{page.value=1;selection.value=[]})
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))})
watch(()=>props.defaultPageSize,v=>{pageSize.value=v||10;page.value=1})
function at(value){return value&&!String(value).startsWith('0001')?formatTime(value):'—'}
function amount(value){return value!==undefined&&value!==null&&value!==''?Number(value).toFixed(2):'—'}
function associated(row){return data.cases.filter(c=>c.card_id===row.card.id)}
async function load(){const result=await api('/api/nexovcc/dashboard');if(!disposed)Object.assign(data,result)}
async function loadJob(){const result=await api('/api/nexovcc/job');if(!disposed)job.value=result;return result}
async function poll(){clearTimeout(pollTimer);try{const j=await loadJob();if(disposed)return;if(j.status==='running'){await load();pollTimer=setTimeout(poll,1200)}else{busy.value=false;await load();if(j.message)show(j.message,j.status==='completed'?'success':j.status==='attention'?'info':'error')}}catch(e){if(!disposed){show('进度查询暂时失败，正在重新连接：'+e.message,'error');pollTimer=setTimeout(poll,3000)}}}
async function recoverProgress(){if(disposed)return;try{const j=await loadJob();if(j.status==='running')pollTimer=setTimeout(poll,1200)}catch{pollTimer=setTimeout(poll,3000)}}
async function run(input){
 const accepted=await api('/api/nexovcc/run',{method:'POST',body:{...nexovccOperationPayload(input),confirm:true}})
 if(!disposed)job.value=accepted
 // Follow the durable server job; changing pages never cancels a submitted operation.
 let current=accepted
 while(current.status==='running'){
  if(disposed)return null
  await new Promise(resolve=>setTimeout(resolve,1000));current=await loadJob()
  if(current.id!==accepted.id)throw new Error('后台任务已变化，请查看操作记录核实原请求')
 }
 await load();if(current.status==='failed')throw new Error(current.message)
 if(input.action==='sync'&&current.status==='completed')markRefreshed()
 return current
}
async function perform(input){if(running.value)return;busy.value=true;show('正在处理…','info');try{const j=await run(input);if(j)show(j.message,j.status==='completed'?'success':'info')}catch(e){show(e.message+'；请查看操作记录确认结果','error');await recoverProgress()}finally{busy.value=false}}
async function save(){saving.value=true;try{const result=await api('/api/nexovcc/settings',{method:'PUT',body:nexovccSettingsPayload(cfg)});Object.assign(cfg,result,{login:'',password:'',fund_password:'',totp_secret:'',clear_totp:false});show('环球配置已保存')}catch(e){show(e.message,'error')}finally{saving.value=false}}
function addTemplate(){cfg.templates.push({id:crypto.randomUUID(),name:'',product_id:'',amount:'',fee_buffer:'0.00',holder_id:''})}
function openCards(){dialog.value={type:'open',template_id:cfg.templates[0]?.id||'',count:1}}
function cardAction(row,action){dialog.value={type:'action',action,card:row,amount:'',remark:row.card.remark||'',request_id:requestID(),confirm:false}}
function editReturn(row){dialog.value={type:'return',row,state:row.state,reason:'',confirm:false}}
function editLimit(row){dialog.value={type:'limit',row,maximum:row.local?.max_accounts||0}}
function resolve(op){dialog.value={type:'resolve',op,outcome:'query',serial_no:op.serial_no||'',evidence:'',confirm:false}}
function closeDialog(){if(!running.value&&!saving.value)dialog.value=null}
async function submit(){
 const d=dialog.value;if(!d||running.value||saving.value)return
 if(d.type==='open'){await batchOpen(d);return}
 if(d.type==='return'){
  saving.value=true;try{await api('/api/nexovcc/cases/'+encodeURIComponent(d.row.id),{method:'PUT',body:{state:d.state,reason:d.reason,revision:d.row.revision,confirm:d.confirm}});dialog.value=null;await load();show('回款状态已保存')}catch(e){show(e.message,'error')}finally{saving.value=false};return
 }
 if(d.type==='limit'){
  saving.value=true;try{await api('/api/gptpay/cards/'+encodeURIComponent(d.row.card.id),{method:'PUT',body:{max_accounts:Number(d.maximum)}});dialog.value=null;await load();show('单卡开通上限已保存')}catch(e){show(e.message,'error')}finally{saving.value=false};return
 }
 if(!d.confirm){show('请勾选确认后再提交','error');return}
 dialog.value=null
 if(d.type==='resolve')await perform({action:'resolve',request_id:d.op.id,outcome:d.outcome,serial_no:d.serial_no,evidence:d.evidence})
 else await perform({action:d.action,card_id:d.card.card.id,amount:d.amount,remark:d.remark,request_id:d.request_id})
}
async function batchOpen(d){
 const count=Number(d.count);if(!Number.isInteger(count)||count<1||count>100||!d.template_id){show('请选择模板，数量须为 1～100','error');return}
 if(!d.confirm){show('请确认开卡将扣除账户资金','error');return}
 dialog.value=null;batch.value={running:true,done:0,total:count,title:'批量开卡'};busy.value=true
 try{for(let i=0;i<count;i++){const j=await run({action:'open',template_id:d.template_id,request_id:requestID()});if(!j)return;if(j.operation?.status!=='succeeded')throw new Error(j.operation?.error||'原开卡结果待核实，已停止后续开卡');batch.value.done++}show('开卡完成，卡片已加入 Pro 银行卡列表')}
 catch(e){show(e.message,'error');await recoverProgress()}finally{busy.value=false;if(batch.value)batch.value.running=false}
}
async function batchCancel(){
 const rows=data.cards.filter(r=>selection.value.includes(r.card.id));if(!rows.length||running.value)return
 if(!window.confirm(`销卡 ${rows.length} 张？请先确认回款到账并完成余额提现。`))return
 batch.value={running:true,done:0,total:rows.length,title:'批量销卡'};busy.value=true
 try{for(const row of rows){const reason=cancelReason(row,data.operations);if(reason)throw new Error(`尾号 ${row.card.last4}：${reason}`);const j=await run({action:'cancel',card_id:row.card.id,request_id:requestID()});if(!j)return;batch.value.done++;if(j.operation?.status!=='succeeded')throw new Error('销卡已提交，等待余额回款核实；已暂停后续销卡')}show('所选卡片已销卡')}
 catch(e){show(e.message,'error');await recoverProgress()}finally{busy.value=false;if(batch.value)batch.value.running=false;selection.value=[]}
}
async function reveal(row){try{privateInfo.value=await api('/api/nexovcc/cards/'+encodeURIComponent(row.card.id)+'/private',{method:'POST',body:{}});clearTimeout(privateTimer);privateTimer=setTimeout(()=>{privateInfo.value=null},30000)}catch(e){show(e.message,'error')}}
async function toggle(row){if(running.value)return;saving.value=true;try{await api('/api/gptpay/cards/'+encodeURIComponent(row.card.id),{method:'PUT',body:{enabled:!row.local.enabled}});await load()}catch(e){show(e.message,'error')}finally{saving.value=false}}
onMounted(async()=>{try{const settings=await api('/api/nexovcc/settings');if(disposed)return;Object.assign(cfg,settings);await load();await loadJob();ready.value=true;if(job.value.status==='running'){poll();return}if(cfg.enabled&&refreshDue(cfg.page_refresh_seconds))await perform({action:'sync'})}catch(e){show(e.message,'error')}})
onBeforeUnmount(()=>{disposed=true;clearTimeout(pollTimer);clearTimeout(privateTimer);privateInfo.value=null;cfg.login=cfg.password=cfg.fund_password=cfg.totp_secret=''})
</script>

<template>
 <div class="nex-page">
  <header class="heading"><div><span class="eyebrow">GLOBAL CARD PLATFORM</span><h1><Globe :size="26"/>环球卡台</h1><p>卡片、开通账号与资金操作</p></div><div class="actions"><button class="btn ghost" :disabled="running||!ready" @click="tab='settings'"><Settings2 :size="16"/>配置与模板</button><button class="btn ghost" :disabled="running||!cfg.enabled" @click="perform({action:'sync'})"><RefreshCw :size="16"/>{{running?'处理中…':'同步数据'}}</button><button class="btn primary" :disabled="running||!cfg.enabled||!cfg.templates.length" @click="openCards"><Plus :size="16"/>开卡</button></div></header>
  <MessageBar :message="message"/>
  <div v-if="running||batch" class="progress" role="status"><Clock3 :size="18"/><div><strong>{{batch?.running?batch.title:job.message||'正在处理'}}</strong><small v-if="batch">{{batch.done}} / {{batch.total}} 张</small><small v-else>{{job.done||0}} / {{job.total||1}}</small><progress :value="batch?.running?batch.done:job.done||0" :max="batch?.running?batch.total:job.total||1"/></div><button v-if="batch&&!batch.running" class="icon-button" @click="batch=null"><X :size="16"/></button></div>
  <div class="overview"><article><span>账户余额</span><strong>{{amount(data.balance.amount)}} <small>USD</small></strong><button class="text-link" :disabled="running||!cfg.enabled" @click="perform({action:'balance'})">查询余额</button></article><article><span>冻结金额</span><strong>{{amount(data.balance.frozen)}} <small>USD</small></strong><small>按平台返回单独展示</small></article><article><span>卡片余额</span><strong>{{typeof cardTotal==='number'?cardTotal.toFixed(2):cardTotal}} <small>USD</small></strong><small>未销卡 {{activeCards.length}} 张 · 余额快照</small></article><article><span>可用卡片</span><strong>{{selectable}} <small>张</small></strong><small>符合 Pro 开通条件</small></article></div>
  <nav class="tabs"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id">{{item.name}}</button></nav>
  <div v-if="!ready" class="panel empty">正在读取环球卡台…</div>
  <template v-else-if="tab!=='settings'">
   <div class="toolbar"><div v-if="tab==='cards'" class="filters"><button :class="{selected:filter==='normal'}" @click="filter='normal'">正常</button><button :class="{selected:filter==='closed'}" @click="filter='closed'">销卡</button></div><input v-model="search" type="search" placeholder="搜索账号、卡片尾号或操作编号"/><button v-if="tab==='cards'" class="btn ghost" :disabled="running||!selection.length" @click="batchCancel">批量销卡 {{selection.length||''}}</button></div>
   <section class="panel table-wrap" v-if="tab==='cards'"><table><thead><tr><th></th><th>卡片</th><th>状态</th><th>余额 USD</th><th>开通 / 上限</th><th>关联账号</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.card.id"><td><input v-model="selection" type="checkbox" :value="row.card.id" :disabled="!!cancelReason(row,data.operations)||running"/></td><td><strong>•••• {{row.card.last4||'待同步'}}</strong><small>开卡：{{at(row.card.created_at)}}</small><small>{{row.card.bin}} · {{row.card.serial_no}}</small><small v-if="row.card.remark">{{row.card.remark}}</small></td><td><span v-if="!row.card.imported" class="badge">{{cardState(row)}}</span><PaymentCardStatus v-else :card="row.local"/><small v-if="row.card.error" class="danger-text">{{row.card.error}}</small></td><td><strong>{{amount(row.card.balance)}}</strong><small>{{at(row.card.balance_at)}}</small></td><td>{{row.local?.opened_accounts||0}} / {{row.local?.account_limit||cfg.default_max_accounts}}<small>在途 {{row.local?.pending_accounts||0}}</small><button class="text-link" :disabled="!row.card.imported||running" @click="editLimit(row)">修改上限</button></td><td><details><summary>{{associated(row).length}} 个账号</summary><div v-for="a in associated(row)" :key="a.id" class="case-line"><span>{{a.email}}</span><small>{{returnStates[a.state]}}<template v-if="a.state==='waiting'"> · {{at(a.requested_at||a.updated_at)}}</template></small><button class="text-link" :disabled="running" @click="editReturn(a)">调整状态</button></div></details></td><td><div class="row-actions"><button class="text-link" :disabled="running" @click="perform({action:'refresh',card_id:row.card.id})">刷新 / 余额</button><button class="text-link" :disabled="!row.card.imported" @click="reveal(row)">查看卡密</button><template v-if="row.card.status!=='4'"><button class="text-link" :disabled="running||!row.card.imported" @click="toggle(row)">{{row.local.enabled?'禁用':'启用'}}</button><button v-for="act in ['deposit','withdraw','freeze','unfreeze','remark']" :key="act" class="text-link" :disabled="running" @click="cardAction(row,act)">{{operationNames[act]}}</button><button class="text-link danger-text" :disabled="running||!!cancelReason(row,data.operations)" :title="cancelReason(row,data.operations)" @click="cardAction(row,'cancel')">销卡</button></template></div></td></tr><tr v-if="!visible.length"><td colspan="7" class="empty">{{cfg.enabled?'暂无匹配卡片，可同步已有卡或新建卡片':'先到「配置与模板」连接环球卡台'}}</td></tr></tbody></table></section>
   <section v-else-if="tab==='returns'" class="panel table-wrap"><table><thead><tr><th>账号</th><th>银行卡</th><th>回款状态</th><th>核实依据</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{row.email}}<small>{{row.plan}}</small></td><td>•••• {{row.last4}}</td><td><span class="badge">{{returnStates[row.state]}}</span><small v-if="row.state==='waiting'">{{at(row.requested_at||row.updated_at)}}</small></td><td>{{row.reason||'—'}}<small>{{at(row.updated_at)}}</small></td><td><button class="text-link" :disabled="running" @click="editReturn(row)">调整状态</button></td></tr><tr v-if="!visible.length"><td colspan="5" class="empty">暂无已开通账号的回款记录</td></tr></tbody></table><p class="note">当前接口未提供退款流水；回款需核实实际到账后调整，账号移出仅标记为待回款。</p></section>
   <section v-else class="panel table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>金额 USD</th><th>状态</th><th>详情</th><th></th></tr></thead><tbody><tr v-for="op in visible" :key="op.id"><td>{{at(op.created_at)}}<small>{{op.id}}</small></td><td>{{operationNames[op.action]}}<small>{{op.automatic?'自动':'手动'}} · {{op.serial_no||'未返回卡片'}}</small></td><td>{{amount(op.amount)}}</td><td><span class="badge" :class="{good:op.status==='succeeded'}">{{operationStates[op.status]}}</span></td><td class="wrap">{{op.error||op.evidence||'—'}}</td><td><button v-if="!terminal(op)" class="text-link" :disabled="running" @click="resolve(op)">查询 / 核实</button></td></tr><tr v-if="!visible.length"><td colspan="6" class="empty">暂无操作记录</td></tr></tbody></table></section>
   <Pagination :page="page" :page-size="pageSize" :total="filtered.length" @update:page="page=$event" @update:page-size="pageSize=$event;page=1"/>
  </template>
  <form v-else class="settings" @submit.prevent="save">
   <section class="panel"><header><h2>连接配置</h2><label class="check"><input v-model="cfg.enabled" type="checkbox"/>启用环球卡台</label></header><p class="note">连接 nexovcc.com；已保存的凭据留空表示不修改。</p><div class="fields"><label>登录账号<input v-model="cfg.login" autocomplete="off" :placeholder="cfg.login_present?'已保存，留空不修改':'环球登录账号'"/></label><label>登录密码<input v-model="cfg.password" type="password" autocomplete="new-password" :placeholder="cfg.password_present?'已保存，留空不修改':'登录密码'"/></label><label>资金密码<input v-model="cfg.fund_password" type="password" autocomplete="new-password" :placeholder="cfg.fund_password_present?'已保存，留空不修改':'用于卡密和资金操作'"/></label><label>谷歌验证密钥<input v-model="cfg.totp_secret" type="password" autocomplete="new-password" :placeholder="cfg.totp_present?'已保存，留空不修改':'绑定谷歌验证时填写 Base32 密钥'"/></label><label v-if="cfg.totp_present" class="check"><input v-model="cfg.clear_totp" type="checkbox"/>清除已保存谷歌验证密钥</label></div><div class="actions"><button class="btn primary" :disabled="saving||running">{{saving?'保存中…':'保存配置'}}</button><button type="button" class="btn ghost" :disabled="running||!cfg.enabled" @click="perform({action:'balance'})">测试连接 / 余额</button><button type="button" class="btn ghost" :disabled="running||!cfg.enabled" @click="perform({action:'sync'})">同步产品与卡片</button></div></section>
   <section class="panel"><h2>用卡与刷新</h2><div class="fields"><label>默认每卡最大开通数<input v-model.number="cfg.default_max_accounts" type="number" min="1" max="10000" required/></label><label>重复进入刷新间隔（秒）<input v-model.number="cfg.page_refresh_seconds" type="number" min="5" max="86400" required/></label><label class="check"><input v-model="cfg.single_active_account" type="checkbox"/>一卡同时一个号</label></div><p class="note">成功开通累计计数；同时占用需确认回款后释放。单张卡可独立调整最大开通数。</p></section>
   <section class="panel"><header><h2>开卡模板 <small>{{cfg.templates.length}} 个</small></h2><button type="button" class="btn ghost" @click="addTemplate"><Plus :size="15"/>添加模板</button></header><div v-for="(t,i) in cfg.templates" :key="t.id" class="template-row fields"><label>名称<input v-model="t.name" required maxlength="60" placeholder="例如 Pro 主用卡"/></label><label>产品 / BIN<select v-model="t.product_id" required><option value="">先同步产品后选择</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{p.name}} · {{p.bin}} · 最低 {{p.minimum}} USD</option></select></label><label>开卡充值金额 USD<input v-model="t.amount" type="number" min="0.01" step="0.01" required/></label><label>费用预留 USD<input v-model="t.fee_buffer" type="number" min="0" step="0.01" required/></label><label>持卡人 ID<input v-model="t.holder_id" placeholder="留空自动分配"/></label><button type="button" class="text-link danger-text" @click="cfg.templates.splice(i,1)">删除模板</button></div><p v-if="!cfg.templates.length" class="empty">添加模板后，可在 Pro 配置 → 银行卡与补卡中选择。</p><p class="note">费用预留用于开卡前余额检查，不代表平台实际收费。</p><button class="btn primary" :disabled="saving||running">保存配置与模板</button></section>
  </form>
  <Teleport to="body"><div v-if="dialog" class="modal-backdrop" @click.self="closeDialog"><form class="modal nex-dialog" @submit.prevent="submit"><div class="modal-heading"><h2>{{dialog.type==='open'?'开卡':dialog.type==='return'?'调整回款状态':dialog.type==='limit'?'单卡开通上限':dialog.type==='resolve'?'核实原操作':operationNames[dialog.action]}}</h2><button type="button" class="icon-button" :disabled="running||saving" @click="closeDialog"><X :size="18"/></button></div>
   <template v-if="dialog.type==='open'"><label class="field">开卡模板<select v-model="dialog.template_id" required><option v-for="t in cfg.templates" :key="t.id" :value="t.id">{{t.name}} · {{t.amount}} USD</option></select></label><label class="field">开卡数量<input v-model.number="dialog.count" type="number" min="1" max="100" required/></label><p>逐张开卡并导入 Pro；遇到失败或未知结果即停止。</p><label class="check"><input v-model="dialog.confirm" type="checkbox" required/>确认从环球账户扣款开卡</label></template>
   <template v-else-if="dialog.type==='limit'"><label class="field">最大开通数<input v-model.number="dialog.maximum" type="number" min="0" max="10000" required/></label><p>填 0 沿用环球默认上限；已有成功次数和在途占用不会清空。</p></template>
   <template v-else-if="dialog.type==='return'"><p>{{dialog.row.email}} · 尾号 {{dialog.row.last4}}</p><label class="field">回款状态<select v-model="dialog.state"><option v-for="(name,state) in returnStates" :key="state" :value="state">{{name}}</option><option value="auto">恢复自动判断</option></select></label><label class="field">核实依据<textarea v-model="dialog.reason" required minlength="3" maxlength="500" placeholder="例如已在环球后台确认退款到账"/></label><label class="check"><input v-model="dialog.confirm" type="checkbox" required/>已核实该账号实际付款 / 回款状态</label></template>
   <template v-else-if="dialog.type==='resolve'"><p>{{operationNames[dialog.op.action]}} · {{dialog.op.id}}</p><label class="field">处理方式<select v-model="dialog.outcome"><option value="query">查询原操作结果</option><option v-if="dialog.op.action!=='open'" value="succeeded">人工确认已完成并到账</option><option value="failed">人工确认未执行 / 未扣款</option></select></label><label v-if="dialog.op.action==='open'&&!dialog.op.serial_no" class="field">原卡序列号<input v-model="dialog.serial_no" placeholder="同步后核对备注与操作编号，填写对应卡序列号"/></label><label v-if="dialog.outcome!=='query'" class="field">核实依据<textarea v-model="dialog.evidence" minlength="5" maxlength="500" required/></label><label class="check"><input v-model="dialog.confirm" type="checkbox" required/>确认核实原操作，不重复提交资金请求</label></template>
   <template v-else><p>银行卡尾号 {{dialog.card.card.last4}}</p><label v-if="['deposit','withdraw'].includes(dialog.action)" class="field">金额 USD<input v-model="dialog.amount" type="number" min="0.01" step="0.01" required/></label><label v-if="dialog.action==='remark'" class="field">备注<input v-model="dialog.remark" maxlength="40"/></label><p v-if="dialog.action==='withdraw'">提现后须保留 1 USD。核实提现到账后才能继续销卡。</p><p v-if="dialog.action==='cancel'">请确认退款已到账、提现已到账。销卡后剩余余额回到账户需核实。</p><label class="check"><input v-model="dialog.confirm" type="checkbox" required/>确认执行{{operationNames[dialog.action]}}</label></template>
   <div class="actions"><button type="button" class="btn ghost" :disabled="running||saving" @click="closeDialog">取消</button><button class="btn primary" :disabled="running||saving">{{running||saving?'处理中…':'确认'}}</button></div>
  </form></div><div v-if="privateInfo" class="modal-backdrop" @click.self="privateInfo=null"><section class="modal nex-dialog"><div class="modal-heading"><h2>卡片信息</h2><button class="icon-button" @click="privateInfo=null"><X :size="18"/></button></div><p class="private-number">{{privateInfo.cardNumber}}</p><p>有效期：{{privateInfo.expMonth}} / {{privateInfo.expYear}}</p><p>CVV：{{privateInfo.cvv}}</p><small>30 秒后自动隐藏</small></section></div></Teleport>
 </div>
</template>

